local RunService = game:GetService("RunService")

local Signal = require(script.Parent.Signal)

local noop = function() end

--[=[
	@interface MotorState
	@within BaseMotor
	@field value number
	@field velocity number
	@field complete boolean
]=]

--[=[
	@class BaseMotor

	Base class for SingleMotor and GroupMotor, manages connections to RunService.
]=]
local BaseMotor = {}
BaseMotor.__index = BaseMotor

function BaseMotor.new()
	return setmetatable({
		_onStep = Signal.new(),
		_onStart = Signal.new(),
		_onComplete = Signal.new(),
	}, BaseMotor)
end

--[=[
	Fired when the motor's state updates.

	@param handler (state: unknown) -> nil
	@return Connection
]=]
function BaseMotor:onStep(handler)
	return self._onStep:connect(handler)
end

--[=[
	Fired whenever BaseMotor:start() is called.

	If `useImplicitConnections` is set to true, this will be called whenever setGoal is called.

	@param handler () -> nil
	@return Connection
]=]
function BaseMotor:onStart(handler)
	return self._onStart:connect(handler)
end

--[=[
	Fired whenever a motor finishes.

	It's recommended to use onStep and check for a certain threshold (i.e. 99% of the way there) instead of using this, as it can often take a while to fire.

	@param handler () -> nil
	@return Connection
]=]
function BaseMotor:onComplete(handler)
	return self._onComplete:connect(handler)
end

--[=[
	Creates a connection to RunService if there isn't one already.

	@return nil
]=]
function BaseMotor:start()
	if not self._connection then
		self._connection = RunService.RenderStepped:Connect(function(deltaTime)
			self:step(deltaTime)
		end)
	end
end

--[=[
	Removes the connection to RunService if it exists.

	@return nil
]=]
function BaseMotor:stop()
	if self._connection then
		self._connection:Disconnect()
		self._connection = nil
	end
end

BaseMotor.destroy = BaseMotor.stop

BaseMotor.step = noop
BaseMotor.getValue = noop
BaseMotor.setGoal = noop

--[=[
	Returns the type of motor. Used for isMotor.

	@return string
]=]
function BaseMotor:__tostring()
	return "Motor"
end

return BaseMotor

return function()
	local GroupMotor = require(script.Parent.GroupMotor)

	local Instant = require(script.Parent.Instant)
	local Spring = require(script.Parent.Spring)

	it("should complete when all child motors are complete", function()
		local motor = GroupMotor.new({
			A = 1,
			B = 2,
		}, false)

		expect(motor._complete).to.equal(true)

		motor:setGoal({
			A = Instant.new(3),
			B = Spring.new(4, { frequency = 7.5, dampingRatio = 1 })
		})

		expect(motor._complete).to.equal(false)

		motor:step(1/60)

		expect(motor._complete).to.equal(false)

		for _ = 1, 0.5 * 60 do
			motor:step(1/60)
		end

		expect(motor._complete).to.equal(true)
	end)

	it("should start when the goal is set", function()
		local motor = GroupMotor.new({
			A = 0,
		}, false)

		local bool = false
		motor:onStart(function()
			bool = not bool
		end)

		motor:setGoal({
			A = Instant.new(1)
		})

		expect(bool).to.equal(true)

		motor:setGoal({
			A = Instant.new(1)
		})

		expect(bool).to.equal(false)
	end)

	it("should properly return all values", function()
		local motor = GroupMotor.new({
			A = 1,
			B = 2,
		}, false)

		local value = motor:getValue()

		expect(value.A).to.equal(1)
		expect(value.B).to.equal(2)
	end)

	it("should error when a goal is given to GroupMotor.new", function()
		local success = pcall(function()
			GroupMotor.new(Instant.new(0))
		end)

		expect(success).to.equal(false)
	end)

	it("should error when a single goal is provided to GroupMotor:step", function()
		local success = pcall(function()
			GroupMotor.new({ a = 1 }):setGoal(Instant.new(0))
		end)

		expect(success).to.equal(false)
	end)
end

--[=[
	@class Instant

	Represents an Instant goal. Always returns a complete state with the provided value.
]=]
local Instant = {}
Instant.__index = Instant

--[=[
	Creates a new Instant.

	@param targetValue number
	@return Instant
]=]
function Instant.new(targetValue)
	return setmetatable({
		_targetValue = targetValue,
	}, Instant)
end

--[=[
	Returns a complete MotorState with `value` set to `targetValue`.
]=]
function Instant:step()
	return {
		complete = true,
		value = self._targetValue,
	}
end

return Instant

--[=[
	@interface LinearOptions
	@within Linear
	@field velocity number -- How fast the goal should move towards the target. Default: 1
]=]

--[=[
	@class Linear

	Represents a linear Goal. Moves towards the target at a specified velocity.
]=]
local Linear = {}
Linear.__index = Linear

--[=[
	Creates a new Linear.

	@param targetValue number
	@param options LinearOptions
	@return Linear
]=]
function Linear.new(targetValue, options)
	assert(targetValue, "Missing argument #1: targetValue")

	options = options or {}

	return setmetatable({
		_targetValue = targetValue,
		_velocity = options.velocity or 1,
	}, Linear)
end

--[=[
	Advances the specified MotorState by `deltaTime * velocity` and returns a new MotorState.
]=]
function Linear:step(state, dt)
	local position = state.value
	local velocity = self._velocity -- Linear motion ignores the state's velocity
	local goal = self._targetValue

	local dPos = dt * velocity

	local complete = dPos >= math.abs(goal - position)
	position = position + dPos * (goal > position and 1 or -1)
	if complete then
		position = self._targetValue
		velocity = 0
	end

	return {
		complete = complete,
		value = position,
		velocity = velocity,
	}
end

return Linear
